import java.util.Scanner;

public class e1542easy {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int mod = scanner.nextInt();
        solve(n, mod);
        scanner.close();
    }

    public static void solve(int n, int mod) {
        java.util.List<long[]> inversions = new java.util.ArrayList<>();
        inversions.add(new long[]{1});
        for (int i = 1; i < n; i++) {
            long[] last = inversions.get(i - 1);
            long[] next = new long[i * (i + 1) / 2 + 1];
            for (int j = 0; j < next.length; j++) {
                long e = 0;
                for (int k = Math.min(j, i); k >= 0; k--) {
                    if (j - k < last.length) {
                        e += last[j - k];
                        e %= mod;
                    }
                }
                next[j] = e;
            }
            inversions.add(next);
        }

        long[] perms = new long[n];
        perms[0] = 0;
        for (int i = 1; i < n; i++) {
            long c = (perms[i - 1] * (i + 1)) % mod;
            long[] inv = inversions.get(i - 1);
            for (int j = 0; j < inv.length; j++) {
                for (int k = j + 2; k < inv.length; k++) {
                    long m = Math.min(k - j, i + 1);
                    long term = ((inv[j] * inv[k]) % mod) * ((m - 1) * (2 * i - (m - 2)) / 2);
                    c = (c + term) % mod;
                }
            }
            perms[i] = c;
        }
        System.out.println(perms[n - 1]);
    }
}
